package pbl6.ctsv.mghp.configuration;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;
final class RoundService {
 final ConfigurationRepository r;final ObjectMapper json;final Clock clock;
 RoundService(ConfigurationRepository r,ObjectMapper json,Clock clock){this.r=r;this.json=json;this.clock=clock;}
 PolicyService.View detail(long id,boolean manager){byte[] f=r.fence("mghp_dot_xet",id);var b=r.roundView(id,manager);return new PolicyService.View(b,manager?ConfigRules.tag("round:"+id+":manager",f,b,json):null);}
 Object list(boolean manager,Long semester,int[] page){if(semester!=null)semester(semester);String where=" WHERE (? IS NULL OR hoc_ky_id=?)"+(manager?"":" AND trang_thai IN(N'open',N'closed',N'completed')");
  var items=r.rows("SELECT id,ma_dot_xet code,hoc_ky_id semesterId,ten name,trang_thai status,thoi_diem_mo opensAt,han_nop submissionDeadline,han_ra_soat reviewDeadline FROM dbo.mghp_dot_xet"+where+" ORDER BY CASE WHEN thoi_diem_mo IS NULL THEN 1 ELSE 0 END,thoi_diem_mo DESC,id DESC OFFSET ? ROWS FETCH NEXT ? ROWS ONLY",semester,semester,(long)page[0]*page[1],page[1]);long total=r.jdbc.queryForObject("SELECT COUNT_BIG(*) FROM dbo.mghp_dot_xet"+where,Long.class,semester,semester);return Map.of("items",items,"page",page[0],"size",page[1],"totalElements",total);
 }
 Map<String,Object> semester(long id){return r.one("SELECT id,ngay_bat_dau startDate,ngay_ket_thuc endDate,trang_thai_xac_minh_moc state,can_cu_xac_minh_moc evidence FROM dbo.hoc_ky WITH(UPDLOCK,HOLDLOCK) WHERE id=?",id);}
 void references(JsonNode n,long actor){semester(ConfigRules.id(n.path("semesterId").asText()));var policyIds=new HashSet<String>();var ids=new TreeSet<Long>();for(var p:n.path("policyVersions"))ids.add(ConfigRules.id(p.path("policyVersionId").asText()));for(long id:ids){r.fence("mghp_phien_ban_chinh_sach",id);var pv=r.policyView(id);if(!policyIds.add(pv.get("policyId").toString()))throw ConfigFailure.invalid("policyVersions");}
  for(var p:n.path("policyVersions"))if(!p.path("applicationTemplateFileId").isNull())file(ConfigRules.id(p.path("applicationTemplateFileId").asText()),actor);
 }
 void file(long id,long actor){
  var file=r.one("SELECT trang_thai_luu_tru state,nguoi_so_huu_id ownerId,nguoi_tai_len_id uploaderId,kieu_noi_dung mime,thoi_diem_xoa deleted FROM dbo.tep_dinh_kem WITH(UPDLOCK,HOLDLOCK) WHERE id=?",id);
  boolean owned=Objects.equals(file.get("ownerId"),Long.toString(actor))||Objects.equals(file.get("uploaderId"),Long.toString(actor));
  // This method is reached only after online MGHP-manager authorization. Bound templates inherit round access (TEP02).
  boolean bound=r.jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_chinh_sach_dot_xet b JOIN dbo.mghp_dot_xet d ON d.id=b.dot_xet_id WHERE b.tep_mau_don_id=?",Integer.class,id)>0;
  if(!owned&&!bound)throw new ConfigFailure(404,"NOT_FOUND");
  if(!"available".equals(file.get("state"))||file.get("deleted")!=null||!"application/pdf".equals(file.get("mime")))throw new ConfigFailure(409,"ROUND_NOT_READY");
 }
 PolicyService.View create(JsonNode n,long actor){RoundRules.validate(n);references(n,actor);if(r.jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_dot_xet WITH(UPDLOCK,HOLDLOCK) WHERE ma_dot_xet=?",Integer.class,n.path("code").asText())!=0)throw new ConfigFailure(409,"ROUND_CODE_CONFLICT");var v=ConfigurationRepository.values(n,ConfigurationRepository.ROUND);v.put("trang_thai","draft");v.put("nguoi_tao_id",actor);v.put("thoi_diem_tao",now());v.put("thoi_diem_cap_nhat",now());long id=r.insert("mghp_dot_xet",v);r.roundChildren(id,n,false);r.audit(actor,"ROUND_CREATE","mghp_dot_xet",id,null);return detail(id,true);}
 PolicyService.View update(long id,JsonNode n,String tag,long actor){RoundRules.validate(n);var hint=r.roundView(id,true);var semesters=new TreeSet<Long>();semesters.add(ConfigRules.id(hint.get("semesterId").toString()));semesters.add(ConfigRules.id(n.path("semesterId").asText()));for(long s:semesters)semester(s);references(n,actor);var f=r.fence("mghp_dot_xet",id);var old=detail(id,true);ConfigRules.match(old.tag(),tag);var body=r.roundView(id,true);if(!"draft".equals(body.get("status"))||body.get("configLockedAt")!=null||r.jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_ho_so WHERE dot_xet_id=?",Integer.class,id)>0)throw new ConfigFailure(409,"ROUND_CONFIG_LOCKED");
  if(r.jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_dot_xet WHERE ma_dot_xet=? AND id<>?",Integer.class,n.path("code").asText(),id)>0)throw new ConfigFailure(409,"ROUND_CODE_CONFLICT");var v=ConfigurationRepository.values(n,ConfigurationRepository.ROUND);v.put("thoi_diem_cap_nhat",now());r.cas("mghp_dot_xet",id,f,v);r.roundChildren(id,n,true);r.audit(actor,"ROUND_UPDATE","mghp_dot_xet",id,null);return detail(id,true);
 }
 PolicyService.View transition(long id,String action,String tag,String reason,long actor){var hint=r.roundView(id,true);var calendar=semester(ConfigRules.id(hint.get("semesterId").toString()));for(var p:(List<?>)hint.get("policyVersions")){var row=(Map<?,?>)p;r.fence("mghp_phien_ban_chinh_sach",ConfigRules.id(row.get("policyVersionId").toString()));}
  var f=r.fence("mghp_dot_xet",id);var old=detail(id,true);ConfigRules.match(old.tag(),tag);var b=r.roundView(id,true);String state=(String)b.get("status"),target=switch(action){case "open"->"open";case "close"->"closed";default->"completed";};if(target.equals(state))return old;
  var v=new LinkedHashMap<String,Object>();v.put("trang_thai",target);v.put("thoi_diem_cap_nhat",now());
  if(action.equals("open")){if(!"draft".equals(state))throw new ConfigFailure(409,"ROUND_STATE_CONFLICT");ready(b,calendar,actor);v.put("nguoi_khoa_cau_hinh_id",actor);v.put("thoi_diem_khoa_cau_hinh",now());}
  else if(action.equals("close")){if(!"open".equals(state))throw new ConfigFailure(409,"ROUND_STATE_CONFLICT");}
  else {if(!"closed".equals(state)||pending(id))throw new ConfigFailure(409,"ROUND_STATE_CONFLICT");}
  r.cas("mghp_dot_xet",id,f,v);
  if(action.equals("open")){var notice=new LinkedHashMap<String,Object>();notice.put("ma_phan_he","MGHP");notice.put("tieu_de",b.get("name"));notice.put("noi_dung",b.get("declarationGuidance"));notice.put("loai_doi_tuong","mghp_dot_xet");notice.put("doi_tuong_id",Long.toString(id));notice.put("trang_thai","published");notice.put("thoi_diem_cong_bo",now());notice.put("nguoi_tao_id",actor);notice.put("thoi_diem_tao",now());long notification=r.insert("thong_bao",notice);r.jdbc.update("UPDATE dbo.mghp_dot_xet SET thong_bao_dot_xet_id=? WHERE id=?",notification,id);
   r.jdbc.update("INSERT dbo.nguoi_nhan_thong_bao(thong_bao_id,nguoi_dung_id,thoi_diem_tao) SELECT ?,u.id,? FROM dbo.nguoi_dung u WHERE u.dang_hoat_dong=1 AND u.thoi_diem_xoa IS NULL AND EXISTS(SELECT 1 FROM dbo.sinh_vien s WHERE s.nguoi_dung_id=u.id)",notification,now());
  }
  r.audit(actor,"ROUND_"+action.toUpperCase(Locale.ROOT),"mghp_dot_xet",id,reason);return detail(id,true);
 }
 void ready(Map<String,Object> b,Map<String,Object> semester,long actor){boolean ok="verified".equals(semester.get("state"))&&semester.get("evidence")!=null&&semester.get("startDate")!=null&&semester.get("endDate")!=null&&Boolean.TRUE.equals(b.get("allowRetroactive"))&&"theo_phap_luat".equals(b.get("retroactiveMode"))&&"khoang_ngay_chuyen_vien_xac_nhan".equals(b.get("midSemesterMode"))&&b.get("opensAt")!=null&&b.get("submissionDeadline")!=null&&b.get("reviewDeadline")!=null;
  if(!ok)throw new ConfigFailure(409,"ROUND_NOT_READY");Instant start=Instant.parse(b.get("opensAt").toString()),end=Instant.parse(b.get("submissionDeadline").toString()),review=Instant.parse(b.get("reviewDeadline").toString());if(start.isAfter(end)||end.isAfter(review)||clock.instant().isAfter(end))throw new ConfigFailure(409,"ROUND_NOT_READY");var list=(List<?>)b.get("policyVersions");if(list.isEmpty())throw new ConfigFailure(409,"ROUND_NOT_READY");
  var from=LocalDate.parse(semester.get("startDate").toString());var until=LocalDate.parse(semester.get("endDate").toString());for(var x:list){var p=(Map<?,?>)x;var pv=r.policyView(ConfigRules.id(p.get("policyVersionId").toString()));if(!"locked".equals(pv.get("status"))||pv.get("lockedAt")==null||pv.get("ruleVerificationStatus")==null||pv.get("effectiveFrom")==null||LocalDate.parse(pv.get("effectiveFrom").toString()).isAfter(until)||pv.get("effectiveUntil")!=null&&LocalDate.parse(pv.get("effectiveUntil").toString()).isBefore(from))throw new ConfigFailure(409,"ROUND_NOT_READY");if(p.get("applicationTemplateFileId")!=null)file(ConfigRules.id(p.get("applicationTemplateFileId").toString()),actor);}
 }
 boolean pending(long id){int rounds=r.jdbc.queryForObject("SELECT COUNT(*) FROM dbo.mghp_yeu_cau_bo_sung y WITH(UPDLOCK,HOLDLOCK) JOIN dbo.mghp_ho_so h ON h.id=y.ho_so_id WHERE (y.dot_tiep_nhan_id=? OR (y.dot_tiep_nhan_id IS NULL AND h.dot_xet_id=?)) AND (y.trang_thai IS NULL OR y.trang_thai NOT IN(N'completed',N'cancelled') OR y.trang_thai=N'completed' AND EXISTS(SELECT 1 FROM dbo.mghp_noi_dung_bo_sung n WHERE n.yeu_cau_bo_sung_id=y.id AND (n.ket_qua_xu_ly IS NULL OR n.ket_qua_xu_ly NOT IN(N'satisfied',N'unsatisfied',N'not_applicable'))))",Integer.class,id,id);
  int tasks=r.jdbc.queryForObject("SELECT COUNT(*) FROM dbo.cong_viec t WITH(UPDLOCK,HOLDLOCK) WHERE ma_phan_he=N'MGHP' AND (loai_doi_tuong=N'mghp_dot_xet' AND doi_tuong_id=? OR loai_doi_tuong=N'mghp_ho_so' AND EXISTS(SELECT 1 FROM dbo.mghp_ho_so h WHERE h.dot_xet_id=? AND CONVERT(varchar(20),h.id)=t.doi_tuong_id)) AND (trang_thai IS NULL OR trang_thai NOT IN(N'completed',N'cancelled'))",Integer.class,Long.toString(id),id);return rounds+tasks>0;
 }
 OffsetDateTime now(){return OffsetDateTime.ofInstant(clock.instant(),ZoneOffset.UTC);}
}
